  function currentFaction(){return state.current_faction||'PATRIOT';}
  function persist(){try{window.BattleContinuityAudit?.observe(state,'UI_PERSIST');}catch(error){console.warn('Battle audit unavailable',error);}try{storage.setItem(SAVE_KEY,JSON.stringify(state));}catch(_error){}}
  function getArmiesAt(cityId,options={}){return Object.values(state.field_armies).filter(a=>a.location_city_id===cityId&&(!options.faction||a.faction===options.faction)&&(!options.unactedOnly||(!a.acted_this_month&&!a.battle_id))).sort((a,b)=>commanderOrder(a.commander_id)-commanderOrder(b.commander_id)||a.id.localeCompare(b.id));}
  function getCityMilitaryStatus(cityId){return E.militaryStatus(state,cityId);}
  function setCityUnrest(cityId,value,rebellionActive=false){state=E.setCityUnrest(state,cityId,value,rebellionActive);render();window.__cityCommandUI?.refreshMilitaryStatus?.(cityId);return getCityMilitaryStatus(cityId);}
  function statBand(value){if(value<=14)return 0;if(value<=28)return 1;if(value<=42)return 2;if(value<=57)return 3;if(value<=71)return 4;if(value<=85)return 5;return 6;}
  function eligibleAttackArmies(leaderArmyId){const leader=state.field_armies[leaderArmyId],commander=leader&&state.commanders[leader.commander_id],minimum=Number(window.PHASE2_CONFIG?.battle_engine?.attack_start_minimum_manpower??100);if(!leader||!commander||leader.acted_this_month||Number(leader.morale||0)<10||Number(leader.manpower||0)<minimum)return[];if(!['総司令官','方面軍司令官'].includes(commander.role))return[clone(leader)];return getArmiesAt(leader.location_city_id,{faction:leader.faction,unactedOnly:true}).filter(army=>Number(army.morale||0)>=10&&Number(army.manpower||0)>=minimum).map(clone);}
  function previewAttackFormation(leaderArmyId,participantArmyIds,destinationCityId,routeType='ATTACK'){const eligible=eligibleAttackArmies(leaderArmyId),eligibleIds=new Set(eligible.map(a=>a.id)),ids=[...new Set(participantArmyIds||[])];if(!ids.includes(leaderArmyId))ids.unshift(leaderArmyId);if(!ids.length||ids.some(id=>!eligibleIds.has(id)))throw new Error('ATTACK_FORMATION_INVALID');const next=clone(state),beforeManpower=Object.fromEntries(ids.map(id=>[id,next.field_armies[id].manpower]));for(const id of ids)next.field_armies[id].acted_this_month=true;if(routeType==='LANDING_ATTACK'){const cities=window.__cityCommandUI?.getState?.(),origin=cities?.cities?.[next.field_armies[leaderArmyId].location_city_id],destination=cities?.cities?.[destinationCityId],calendar=next.calendar;if(origin&&destination&&window.NavalControlEngine){const profile=window.NavalControlEngine.seaRouteProfile(cities,origin.geography.sea_zone_id,destination.geography.sea_zone_id,next.field_armies[leaderArmyId].faction,'LANDING',`${calendar.year}-${String(calendar.month).padStart(2,'0')}`);for(const id of ids){const before=beforeManpower[id]||0;next.field_armies[id].manpower=before>0&&profile.arrival_rate>0?Math.max(1,Math.floor(before*profile.arrival_rate)):0;}next.action_log=next.action_log||[];next.action_log.push({type:'LANDING_TRANSIT_ATTRITION',faction:next.field_armies[leaderArmyId].faction,army_ids:ids,destination_city_id:destinationCityId,arrival_rate:profile.arrival_rate,worst_zone_id:profile.worst_zone_id,worst_stage:profile.worst_stage.key,before_manpower:beforeManpower,after_manpower:Object.fromEntries(ids.map(id=>[id,next.field_armies[id].manpower]))});}}E.appendAction(next,{type:'JOINT_ATTACK_FORMED',faction:next.field_armies[leaderArmyId].faction,army_id:leaderArmyId,participant_army_ids:ids,destination_city_id:destinationCityId,participant_limit:null,route_type:routeType});return{state:next,armies:ids.map(id=>clone(next.field_armies[id]))};}
  function registerAttackFormation(leaderArmyId,participantArmyIds,destinationCityId,routeType='ATTACK'){const preview=previewAttackFormation(leaderArmyId,participantArmyIds,destinationCityId,routeType);state=preview.state;render();return preview.armies;}
  function normalizeCommandStarSizes(){document.querySelectorAll('.field-army-marker .theater-star').forEach(star=>star.setAttribute('d','M0,-13 3,-6 11,-6 5,-1 7,7 0,2 -7,7 -5,-1 -11,-6 -3,-6Z'));}
  function render(){const faction=currentFaction(),current=state.factions[faction],name=faction==='PATRIOT'?'アメリカ独立派':'イギリス王党派';$('phase2-phase-title').textContent=`${name}　指令フェーズ`;$('phase2-calendar').textContent=`${state.calendar.year}年${state.calendar.month}月`;const starSummary=window.PoliticalPhaseEngine?.strategicStars?.(window.__cityCommandUI?.getState?.(),state,window.POLITICAL_PHASE_CONFIG),securedStars=Number(starSummary?.[faction])||0;$('phase2-strategic-stars').innerHTML=`戦略支配 ★<strong>${securedStars}</strong>`;$('phase2-current').innerHTML=`コマンド残 <strong>${current.commands_remaining}／3</strong>`;$('phase2-funds').innerHTML=`軍資金 <strong>${(Number(current.treasury)||0).toLocaleString()}</strong>`;persist();window.__cityCommandUI?.setFaction?.(faction);window.__cityCommandUI?.syncCalendar?.(state.calendar);renderArmyMarkers();normalizeCommandStarSizes();if(selectedCityId)renderCityArmies(selectedCityId);if(openedArmyId&&!modal.hidden)renderArmyModal(openedArmyId);}
  function displayRole(commander,isRepresentative=false){if(commander.role==='総司令官'||commander.role==='方面軍司令官')return commander.role;return isRepresentative?'都市司令官':'';}
  function roleBadge(commander,role=commander.role){if(role==='総司令官')return'<span class="role-badge chief-badge">☆総司令官</span>';if(role==='方面軍司令官')return'<span class="role-badge theater-badge">☆方面軍司令官</span>';if(role==='都市司令官')return'<span class="role-badge city-commander-badge">☆都市司令官</span>';return'';}
  function representativeArmy(list){return [...list].sort((a,b)=>{const ca=state.commanders[a.commander_id],cb=state.commanders[b.commander_id],priority=c=>c.role==='総司令官'?0:c.role==='方面軍司令官'?1:2;return priority(ca)-priority(cb)||commanderOrder(a.commander_id)-commanderOrder(b.commander_id);})[0]||null;}
  function fieldArmyFormationErrorLabel(code){return({FIELD_ARMY_CITY_NOT_CONTROLLED:'自陣営が軍事支配している都市でのみ新軍を編成できます。',FIELD_ARMY_CITY_IN_BATTLE:'戦闘中の都市では新軍を編成できません。',RESERVE_COMMANDER_NOT_FOUND:'編成可能な予備役指揮官がいません。',COMMANDER_ALREADY_ACTIVE:'この指揮官はすでに実働中です。',COMMANDS_EXHAUSTED:'今月のコマンドが残っていません。',TREASURY_INSUFFICIENT:'軍資金が不足しています。',MOBILIZABLE_MANPOWER_INSUFFICIENT:'動員可能数が不足しています。'})[code]||code;}
